"""Generated by the NL to Flow Diagram Encoder Pipeline."""

def DecimalToBinary(n):
    if (n == 0):
        return '0'
    binary_str = ''
    while (n > 0):
        remainder = (n % 2)
        binary_str = (str(remainder) + binary_str)
        n = (n // 2)
    return binary_str

print(DecimalToBinary(10))
